mapper.select:
SELECT cc.contract_id, ccc.cashflow_id source_id, cc.contract_number, cc.contract_name, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = cc.tenant_id ) bp_name, ccc.times, ccc.due_date, ccc.write_off_flag, ( SELECT sc.meaning FROM
sc WHERE sc.code_value = ccc.write_off_flag AND sc. CODE = 'CON.CASHFLOW_WRITE_OFF_FLAG' ) write_off_flag_desc, ccc.cf_item, (SELECT hci.description FROM hls_cashflow_item hci WHERE ccc.cf_item = hci.cf_item AND ccc.cf_item = hci.cf_type ) cf_item_n, ccc.cf_type, ci.description, ccc.principal, ccc.received_principal, ccc.billing_principal, ccc.billing_amount, nvl(ccc.principal, 0) due_amount, nvl(ccc.received_principal, 0) received_amount, cc.business_type, (select min(bp.bp_id) from hls_bp_master bp where cc.tenant_id = bp.bp_id) bp_id, cc.currency, (select fc.currency_name from FND_CURRENCY fc where fc.currency_code = cc.currency) as currency_desc, round(nvl(ccc.received_principal, 0) - nvl(( select round(sum(arl.amount),2) from ACR_RECEIPT_LN arl where arl.source_id = ccc.cashflow_id and arl.source_type = 'CASHFLOW_PRINCIPAL' ),0),2) as amount, nvl((select round(sum(arl.amount),2) from ACR_RECEIPT_LN arl where arl.source_id = ccc.cashflow_id and arl.source_type = 'CASHFLOW_PRINCIPAL'),0) as receive_amount FROM con_contract cc, con_contract_cashflow ccc, hls_cashflow_item ci
cc.contract_id = ccc.contract_id AND ccc.cf_item = ci.cf_item AND ccc.cf_item = 1 AND cc.business_type = 'LEASEBACK' AND (nvl(ccc.received_principal, 0) - nvl(ccc.billing_principal, 0) - nvl(( select round(sum(arl.amount),2) from ACR_RECEIPT_LN arl where arl.source_id = ccc.cashflow_id and arl.source_type = 'CASHFLOW_PRINCIPAL' ),0) > 0 )
and cc.contract_name like concat(concat('%',#{contractName}),'%')
and cc.contract_number like concat(concat('%',#{contractNumber}),'%')
and ccc.times >= #{timesFrom}
and ccc.times <= #{timesTo}
and exists ( SELECT 1 FROM hls_bp_master hbm WHERE hbm.bp_id = cc.tenant_id and hbm.bp_name like concat(concat('%',#{bpName}),'%'))
and ccc.due_date >=#{dueDateFrom}
and ccc.due_date <#{dueDateTo}
